/**
 * The Deed program, as seen from TypeScript: address, PDAs, an IDL-driven instruction builder and account/event decoders.
 * The IDL (`idl/deed_fun.json`) is generated by `anchor build` from the Rust program in `chain/`: nothing here is hand-copied.
 */
import { BN, BorshCoder, EventParser, type Idl } from "@coral-xyz/anchor";
import { PublicKey, SystemProgram, TransactionInstruction } from "@solana/web3.js";
import { ASSOCIATED_TOKEN_PROGRAM_ID, TOKEN_2022_PROGRAM_ID, TOKEN_PROGRAM_ID, getAssociatedTokenAddressSync } from "@solana/spl-token";
import idlJson from "./idl/deed_fun.json";
import { config } from "@/lib/config";

export const IDL = idlJson as unknown as Idl;
export const PROGRAM_ID = new PublicKey(IDL.address);

if (config.programId && config.programId !== IDL.address) {
  // The program id is compiled into the program (declare_id!). A different id in the environment cannot work.
  throw new Error(`NEXT_PUBLIC_DEED_PROGRAM_ID (${config.programId}) does not match the compiled program (${IDL.address}).`);
}

export const coder = new BorshCoder(IDL);
export const eventParser = new EventParser(PROGRAM_ID, coder);

export { TOKEN_PROGRAM_ID, TOKEN_2022_PROGRAM_ID, ASSOCIATED_TOKEN_PROGRAM_ID };

// ------------------------------------------------------------------ PDAs (must mirror chain/programs/deed_fun/src/constants.rs)

const u64le = (n: bigint) => {
  const b = Buffer.alloc(8);
  b.writeBigUInt64LE(n);
  return b;
};
const pda = (seeds: (Buffer | Uint8Array)[]) => PublicKey.findProgramAddressSync(seeds, PROGRAM_ID)[0];

export const configPda = () => pda([Buffer.from("config")]);
export const deedStatePda = (coinMint: PublicKey) => pda([Buffer.from("deed"), coinMint.toBuffer()]);
export const vaultPda = (coinMint: PublicKey) => pda([Buffer.from("vault"), coinMint.toBuffer()]);
export const auctionPda = (deedMint: PublicKey, nonce: bigint) => pda([Buffer.from("auction"), deedMint.toBuffer(), u64le(nonce)]);
export const offerPda = (maker: PublicKey, nonce: bigint) => pda([Buffer.from("offer"), maker.toBuffer(), u64le(nonce)]);

export const ata = (owner: PublicKey, mint: PublicKey, tokenProgram: PublicKey) =>
  getAssociatedTokenAddressSync(mint, owner, true, tokenProgram, ASSOCIATED_TOKEN_PROGRAM_ID);

// ------------------------------------------------------------------ instruction builder

type Arg = BN | bigint | number | boolean | PublicKey | { [k: string]: Arg };
const toBn = (v: Arg): Arg => (typeof v === "bigint" ? new BN(v.toString()) : v instanceof PublicKey || v instanceof BN ? v : typeof v === "object" && v !== null ? (Object.fromEntries(Object.entries(v).map(([k, x]) => [k, toBn(x as Arg)])) as Arg) : v);

interface IdlAccountItem {
  name: string;
  writable?: boolean;
  signer?: boolean;
  address?: string;
}

/**
 * Builds a Deed instruction. `accounts` is keyed by the IDL's account names (snake_case); accounts that the IDL pins to a
 * fixed address (system program, associated token program) are filled in automatically. A missing account throws, so a
 * typo can never silently produce a transaction with the wrong accounts.
 */
export function ix(name: string, args: Record<string, Arg>, accounts: Record<string, PublicKey>): TransactionInstruction {
  const def = IDL.instructions.find((i) => i.name === name);
  if (!def) throw new Error(`Unknown Deed instruction: ${name}`);
  const keys = (def.accounts as unknown as IdlAccountItem[]).map((a) => {
    const pubkey = accounts[a.name] ?? (a.address ? new PublicKey(a.address) : undefined);
    if (!pubkey) throw new Error(`Instruction ${name}: missing account "${a.name}"`);
    return { pubkey, isSigner: !!a.signer, isWritable: !!a.writable };
  });
  const data = coder.instruction.encode(name, Object.fromEntries(Object.entries(args).map(([k, v]) => [k, toBn(v)])));
  return new TransactionInstruction({ programId: PROGRAM_ID, keys, data });
}

export const SYSTEM_PROGRAM = SystemProgram.programId;
